# Small original garage-cat favicon, drawn locally without an image request.
def garage_icon():
    icon = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
    d = ImageDraw.Draw(icon)
    d.polygon([(8, 24), (5, 3), (25, 15), (39, 15), (59, 3), (56, 24), (56, 47), (32, 62), (8, 47)], fill="#d89942", outline="#281e24", width=3)
    d.polygon([(8, 24), (32, 16), (56, 24), (52, 32), (12, 32)], fill="#574656")
    d.line([(16, 35), (26, 39), (22, 43)], fill="#fff0bb", width=4)
    d.line([(48, 35), (38, 39), (42, 43)], fill="#fff0bb", width=4)
    d.arc((18, 39, 49, 55), 0, 160, fill="#fff0bb", width=4)
    return icon

